/* Common */
document.addEventListener("DOMContentLoaded", () => {
	const slideshowCarousel = document.querySelectorAll(".carousel__slider");

	if (slideshowCarousel.length > 0) {
		slideshowCarousel.forEach(el => {
			const slideshowCarouselNext = el.nextElementSibling.querySelector(".swiper-btn-next");
			const slideshowCarouselPrev = el.nextElementSibling.querySelector(".swiper-btn-prev");
			const slideshowPagination = el.querySelector(".carousel__pagination");

			const slider = new Swiper(el, {
				slidesPerView: 1,
				spaceBetween: 10,
				autoplay: {
					delay: 6000
				},
				loop: true,
				autoHeight: true,
				navigation: {
					nextEl: slideshowCarouselNext,
					prevEl: slideshowCarouselPrev,
				},
				pagination: {
					el: slideshowPagination,
					clickable: true
				},
				breakpoint: {
					992: {
						autoHeight: false
					}
				}
			});
		});
	}
});
document.addEventListener("DOMContentLoaded", () => {
	const anchors = document.querySelectorAll('.anchor');

	if (anchors && anchors.length > 0) {
		anchors.forEach(anchor => {
			anchor.addEventListener('click', function (e) {
				if (window.location.hash) {
					document.querySelector(window.location.hash).scrollIntoView({
						behavior: 'smooth'
					});
				}
			});
		});
	}
});
document.addEventListener("DOMContentLoaded", () => {
	const buttonUp = document.querySelector(".button-up");

	if (!buttonUp) return;

	const toggleButton = () => {
		buttonUp.classList.toggle("is-visible", window.scrollY > 400);
	};

	window.addEventListener("scroll", toggleButton, { passive: true });
	toggleButton();

	buttonUp.addEventListener("click", () => {
		window.scrollTo({ top: 0, behavior: "smooth" });
	});
});
document.addEventListener("DOMContentLoaded", () => {
	const header = document.querySelector(".header");

	if (!header) return;

	const burger = header.querySelector(".header__burger");
	const mobile = header.querySelector(".header__mobile");

	const closeMenu = () => {
		header.classList.remove("is-open");
		document.body.classList.remove("is-locked");

		if (burger) {
			burger.setAttribute("aria-expanded", "false");
			burger.setAttribute("aria-label", "Открыть меню");
		}
	};

	if (burger && mobile) {
		burger.addEventListener("click", () => {
			const isOpen = header.classList.toggle("is-open");

			document.body.classList.toggle("is-locked", isOpen);
			burger.setAttribute("aria-expanded", String(isOpen));
			burger.setAttribute("aria-label", isOpen ? "Закрыть меню" : "Открыть меню");
		});

		mobile.querySelectorAll("a").forEach((link) => {
			link.addEventListener("click", closeMenu);
		});

		document.addEventListener("keydown", (e) => {
			if (e.key === "Escape") closeMenu();
		});

		window.addEventListener("resize", () => {
			if (window.innerWidth > 1023) closeMenu();
		});
	}

	const onScroll = () => {
		header.classList.toggle("is-scrolled", window.scrollY > 8);
	};

	onScroll();
	window.addEventListener("scroll", onScroll, { passive: true });

	// Подсветка активного раздела в навигации
	const links = Array.from(document.querySelectorAll(".header__link[href^='#']"));
	const sections = links
		.map((link) => document.querySelector(link.getAttribute("href")))
		.filter(Boolean);

	if (!sections.length || !("IntersectionObserver" in window)) return;

	const observer = new IntersectionObserver(
		(entries) => {
			entries.forEach((entry) => {
				if (!entry.isIntersecting) return;

				links.forEach((link) => {
					link.classList.toggle("is-active", link.getAttribute("href") === `#${entry.target.id}`);
				});
			});
		},
		{ rootMargin: "-45% 0px -50% 0px", threshold: 0 }
	);

	sections.forEach((section) => observer.observe(section));
});
document.addEventListener("DOMContentLoaded", () => {
	const items = document.querySelectorAll("[data-reveal]");

	if (!items.length) return;

	const reducedMotion = window.matchMedia("(prefers-reduced-motion: reduce)").matches;

	if (reducedMotion || !("IntersectionObserver" in window)) {
		items.forEach((item) => item.classList.add("is-visible"));
		return;
	}

	const observer = new IntersectionObserver(
		(entries) => {
			entries.forEach((entry) => {
				if (!entry.isIntersecting) return;

				entry.target.classList.add("is-visible");
				observer.unobserve(entry.target);
			});
		},
		{ rootMargin: "0px 0px -8% 0px", threshold: 0.08 }
	);

	items.forEach((item, index) => {
		if (!item.style.getPropertyValue("--reveal-delay")) {
			item.style.setProperty("--reveal-delay", `${Math.min(index % 4, 3) * 70}ms`);
		}

		observer.observe(item);
	});
});